.qf-panel { animation: qfRise 240ms var(--qf-ease) both; background: var(--qf-surface-warm); border-radius: 20px; box-shadow: 0 0 0 1px var(--qf-hair-12),
    0 40px 80px -40px rgba(28, 25, 23, 0.6),
    inset 0 1px 0 rgba(255, 255, 255, 0.7); display: flex; flex-direction: column; font-family: var(--qf-ui); max-height: 100%; max-width: 640px; overflow: hidden; position: relative; width: 100%; }

html.dark .qf-panel, .qf[data-tone="dark"] .qf-panel { box-shadow: 0 0 0 1px var(--qf-hair-12),
    0 40px 80px -40px rgba(0, 0, 0, 0.8),
    inset 0 1px 0 rgba(255, 255, 255, 0.04); }

@media (hover: none) {
  .qf-legend { display: none; }
  .qf-row-go { opacity: 1; transform: translateX(0px); }
}

@media (max-width: 720px) {
  .qf-portal { padding: 0px; }
  .qf-panel { align-self: stretch; animation-name: qfRiseSheet; border-radius: 0px; height: 100%; max-height: 100%; max-width: none; }
  .qf-body { flex: 1 1 0%; max-height: none; }
}

@container (max-width: 520px) {
  .qf-browse { grid-template-columns: minmax(0px, 1fr); }
  .qf-go { width: 100%; }
  .qf-trigger[aria-label="Open a question"] { padding-inline: 11px; }
}

@keyframes qfRise { 
  0% { opacity: 0; transform: translateY(-10px) scale(0.985); }
  100% { opacity: 1; transform: none; }
}

@keyframes qfRiseSheet { 
  0% { opacity: 0; transform: translateY(16px); }
  100% { opacity: 1; transform: none; }
}

@keyframes qfPop { 
  0% { opacity: 0; transform: scale(0.9); }
  100% { opacity: 1; transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .qf *, .qf ::before, .qf ::after, .qf-portal *, .qf-portal ::before, .qf-portal ::after, .qj *, .qj ::before, .qj ::after { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}

@media (max-width: 600px) {
  .qf-row.qf-row-rc { display: grid; grid-template-columns: minmax(0px, 1fr) auto; gap: 7px 12px; align-items: start; }
  .qf-row-rc > .qf-addr { grid-area: 1 / 1; min-width: 0px; }
  .qf-row-rc > .qf-row-meta { grid-area: 1 / 2; }
  .qf-row-rc > .qf-row-text { grid-area: 2 / 1 / auto / -1; min-width: 0px; }
  .qf-row-rc .qf-row-title { display: block; overflow: visible; white-space: normal; text-overflow: clip; font-size: 15px; line-height: 1.5; }
  .qf-row-rc .qf-snippet, .qf-row-rc .qf-row-go { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .classroom-root .classroom-home *, .classroom-root .classroom-home ::before, .classroom-root .classroom-home ::after { animation: auto ease 0s 1 normal none running none !important; transition: none !important; }
}

@container classroom-home (max-width: 640px) {
  .classroom-root .classroom-home-feature { grid-template-columns: minmax(0px, 1fr); }
  .classroom-root .classroom-home-progress { align-self: stretch; border-left: 0px; border-top: 1px solid var(--home-focus-line); padding: 14px 0px 0px; }
  .classroom-root .classroom-home-focus { padding: 20px; }
  .classroom-root .classroom-home-subtitle { font-size: 16px; }
  .classroom-root .classroom-home-action, .classroom-root .classroom-home-quiet-button, .classroom-root .classroom-home-next-session-line, .classroom-root .classroom-home-more, .classroom-root .classroom-home-done, .classroom-root .classroom-home-day, .classroom-root .classroom-home-context > li { min-height: 44px; }
  .classroom-root .classroom-home-pill { display: none; }
  .classroom-root .classroom-home-row-wrap { align-items: stretch; flex-direction: column; gap: 0px; }
  .classroom-root .classroom-home-done { align-self: flex-start; margin: 0px 0px 8px 26px; }
}

@container classroom-home (max-width: 380px) {
  .classroom-root .classroom-home-actions { display: grid; grid-template-columns: repeat(2, minmax(0px, 1fr)); }
  .classroom-root .classroom-home-action { justify-content: center; padding: 0px 10px; }
  .classroom-root .classroom-home-focus { padding: 18px 16px; }
}

.mc-bootcamp { --accent: 232 208 139; --accent-hover: 242 223 154; --accent-deep: 197 160 89; --accent-dim: 232 208 139; --bg: 245 242 237; --bg-2: 250 247 239; --surface: 255 255 255; --surface-elev: 250 247 239; --border: 26 26 26; --ink: 26 26 26; --ink-soft: 26 26 26 / 0.58; --ink-faint: 26 26 26 / 0.38; --role-conclusion: 16 185 129; --role-premise: 96 165 250; --role-pivot: 249 115 22; --role-opposing: 168 85 247; --role-concession: 250 204 21; --role-background: 148 163 184; --success: 16 185 129; --warn: 250 204 21; --error: 239 68 68; --info: 56 189 248; --t-display: 36px; --t-h1: 28px; --t-h2: 21px; --t-h3: 17px; --t-body: 14px; --t-body-prose: 15px; --t-small: 12.5px; --t-mono: 11.5px; --t-label: 10.5px; --s-1: 4px; --s-2: 8px; --s-3: 12px; --s-4: 16px; --s-6: 24px; --s-8: 32px; --s-12: 48px; --s-16: 64px; --r-2: 2px; --r-3: 2px; --r-5: 2px; --r-8: 2px; --r-full: 9999px; --ease: cubic-bezier(0.4, 0, 0.2, 1); --d-fast: 150ms; --d-mid: 180ms; --d-slow: 220ms; --shadow-1: 0 0 0 1px rgb(var(--ink) / 0.04), 0 1px 2px rgb(var(--ink) / 0.1); --shadow-2: 0 14px 34px rgb(var(--ink) / 0.075); --shadow-3: 0 26px 76px rgb(var(--ink) / 0.12); --shadow-lift: 0 18px 40px -12px rgb(var(--ink) / 0.12); --shadow-press: 0 2px 8px -2px rgb(var(--ink) / 0.08); --glow-accent-soft: 0 0 0 transparent; --glow-accent-strong: 0 0 0 transparent; --grad-surface-soft: linear-gradient(180deg, rgb(255 255 255 / 0.96) 0%, rgb(250 247 239 / 0.98) 100%); --grad-surface-elev: linear-gradient(180deg, rgb(250 247 239 / 0.98) 0%, rgb(245 242 237 / 0.98) 100%); --grad-accent-soft: linear-gradient(135deg, rgb(var(--accent) / 0.12) 0%, rgb(var(--accent) / 0.06) 100%); --grad-accent-strong: linear-gradient(135deg, rgb(var(--accent) / 1) 0%, rgb(var(--accent) / 0.9) 100%); --grad-shimmer: linear-gradient(110deg, transparent 0%, rgb(255 255 255 / 0.4) 40%, rgb(var(--accent) / 0.2) 50%, rgb(255 255 255 / 0.4) 60%, transparent 100%); --grad-card-highlight: linear-gradient(180deg, rgb(255 255 255 / 0.6) 0%, transparent 24%); --border-accent-soft: rgb(var(--accent) / 0.18); --border-accent-mid: rgb(var(--accent) / 0.32); --border-accent-strong: rgb(var(--accent) / 0.50); --texture-paper: radial-gradient(circle at 2px 2px, rgb(26 26 26 / 0.025) 1px, transparent 0); background-color: rgb(var(--bg)); background-image: var(--texture-paper),
    radial-gradient(circle at 16% 0%, rgba(255,255,255,.82), transparent 28%),
    radial-gradient(circle at 88% 3%, rgba(26,26,26,.048), transparent 30%); color: rgb(var(--ink)); font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: var(--t-body); line-height: 1.6; -webkit-font-smoothing: antialiased; text-rendering: optimizelegibility; min-height: 100%; }

@keyframes mc-shine-sweep { 
  0% { transform: translateX(-120%) skewX(-12deg); opacity: 0; }
  40% { opacity: 1; }
  100% { transform: translateX(220%) skewX(-12deg); opacity: 0; }
}

@keyframes mc-thumb-tap { 
  0% { transform: scale(1); }
  50% { transform: scale(0.92); }
  100% { transform: scale(1); }
}

@media (prefers-reduced-motion: reduce) {
  .mc-bootcamp .mc-shimmer { animation: auto ease 0s 1 normal none running none; }
  .mc-bootcamp .mc-shine:hover::after { animation: auto ease 0s 1 normal none running none; }
}

@media (max-width: 767px) {
  .mc-bootcamp .mc-indicator-section { padding: 24px 18px 22px; }
  .mc-bootcamp .mc-indicator-section-body, .mc-bootcamp .mc-indicator-section-rule { font-size: 16px; }
  .mc-bootcamp .mc-indicator-slabs, .mc-bootcamp .mc-indicator-word-grid { grid-template-columns: 1fr; }
  .mc-bootcamp .mc-indicator-slab { grid-template-columns: 1fr; row-gap: 10px; }
  .mc-bootcamp .mc-indicator-slab-copy { max-width: none; }
}

@media print {
  @page { size: letter; margin: 0.4in; }
  .mc-bootcamp, .mc-bootcamp * { background: rgb(255, 255, 255) !important; color: rgb(10, 10, 10) !important; }
  .mc-bootcamp .left-rail, .mc-bootcamp .right-drawer, .mc-bootcamp header[role="banner"], .mc-bootcamp nav, .mc-bootcamp .skip-link, .mc-bootcamp .print-hide { display: none !important; }
  .mc-bootcamp .print-card, .mc-bootcamp .print-card * { background: rgb(255, 255, 255) !important; color: rgb(10, 10, 10) !important; border-color: rgb(153, 153, 153) !important; box-shadow: none !important; }
  .mc-bootcamp .print-card .font-mono { color: rgb(85, 85, 85) !important; }
  .mc-bootcamp .print-card a { text-decoration: none !important; }
  .mc-bootcamp .print-card { padding: 0px !important; }
  .mc-bootcamp .print-card .max-w-prose { max-width: none !important; }
  .mc-bootcamp .print-card .qrc-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.4in; }
  .mc-bootcamp .print-card h1 { font-size: 18pt; }
  .mc-bootcamp .print-card h2 { font-size: 11pt; }
  .mc-bootcamp .print-card p, .mc-bootcamp .print-card li { font-size: 9.5pt; line-height: 1.35; }
}

@keyframes fade-in-up { 
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes bounce { 
  0%, 100% { transform: translateY(-25%); animation-timing-function: cubic-bezier(0.8, 0, 1, 1); }
  50% { transform: none; animation-timing-function: cubic-bezier(0, 0, 0.2, 1); }
}

@keyframes slide-up { 
  0% { opacity: 0; transform: translateY(12px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes spotlight { 
  0% { opacity: 0; transform: translate(-72%, -62%) scale(0.5); }
  100% { opacity: 1; transform: translate(-50%, -40%) scale(1); }
}
